// Manage table (offset mode): every column can filter and sort. A row is
// matched as a document of its standard columns ("@name", "@status", …)
// over its latest registration answers (loaded only when with_answers);
// filters is a JSON array for event_answers_match_all and sort_key is a
// document key sorted by event_list_sort_value.
func (q *Queries) ListEventParticipantsTable(ctx context.Context, arg ListEventParticipantsTableParams) ([]ListEventParticipantsTableRow, error) {
	rows, err := q.db.Query(ctx, listEventParticipantsTable,
		arg.WithAnswers,
		arg.EventID,
		arg.StatusFilter,
		arg.Kind,
		arg.Search,
		arg.Filters,
		arg.SortDir,
		arg.SortKey,
		arg.OffsetVal,
		arg.LimitVal,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListEventParticipantsTableRow{}
	for rows.Next() {
		var i ListEventParticipantsTableRow
		if err := rows.Scan(
			&i.EventID,
			&i.UserID,
			&i.Status,
			&i.CreatedAt,
			&i.DecidedAt,
			&i.DecidedBy,
			&i.TeamID,
			&i.TeamRole,
			&i.InvitedBy,
			&i.Invited,
			&i.InvitedTeamID,
			&i.InvitedToTeam,
			&i.Pseudonym,
			&i.InvitationSentAt,
			&i.InvitationExpiredNotifiedAt,
			&i.FieldsMissing,
			&i.FirstName,
			&i.LastName,
			&i.Email,
			&i.DisplayName,
			&i.TeamHidden,
			&i.TeamName,
			&i.InvitedTeamName,
			&i.LastSeenAt,
			&i.LastLabAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listEventTeamMembers = `-- name: ListEventTeamMembers :many
SELECT participant.team_id::uuid AS team_id,
       participant.user_id,
       participant.team_role,
       participant.pseudonym,
       person.first_name,
       person.last_name,
       person.email,
       presence.last_seen_at                                                           AS last_seen_at,
       COALESCE(lab.at, 'epoch'::timestamptz)::timestamptz AS last_lab_at
FROM event_participants participant
         JOIN users person ON person.id = participant.user_id
         LEFT JOIN event_participant_presence presence ON presence.event_id = participant.event_id AND presence.user_id = participant.user_id
         CROSS JOIN LATERAL (SELECT event_user_last_lab_at(participant.event_id, participant.user_id) AS at) lab
WHERE participant.event_id = $1
  AND participant.team_id = ANY ($2::uuid[])
ORDER BY participant.team_role ASC, person.first_name ASC, person.last_name ASC, participant.user_id ASC
`

