const upsertEventParticipant = `-- name: UpsertEventParticipant :one
INSERT INTO event_participants (event_id, user_id, status, created_at, decided_at, decided_by)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (event_id, user_id) DO NOTHING
RETURNING event_id, user_id, status, created_at, decided_at, decided_by, team_id, team_role, invited_by, invited, invited_team_id, invited_to_team, pseudonym, invitation_sent_at, invitation_expired_notified_at, fields_missing
`

type UpsertEventParticipantParams struct {
	EventID   uuid.UUID          `json:"event_id"`
	UserID    uuid.UUID          `json:"user_id"`
	Status    int16              `json:"status"`
	CreatedAt time.Time          `json:"created_at"`
	DecidedAt pgtype.Timestamptz `json:"decided_at"`
	DecidedBy uuid.NullUUID      `json:"decided_by"`
}

// Join creates the row; a conflicting (event,user) row is left untouched and
// returned (the use case decides whether that is ErrAlreadyParticipant).
func (q *Queries) UpsertEventParticipant(ctx context.Context, arg UpsertEventParticipantParams) (EventParticipant, error) {
	row := q.db.QueryRow(ctx, upsertEventParticipant,
		arg.EventID,
		arg.UserID,
		arg.Status,
		arg.CreatedAt,
		arg.DecidedAt,
		arg.DecidedBy,
	)
	var i EventParticipant
	err := row.Scan(
		&i.EventID,
		&i.UserID,
		&i.Status,
		&i.CreatedAt,
		&i.DecidedAt,
		&i.DecidedBy,
		&i.TeamID,
		&i.TeamRole,
		&i.InvitedBy,
		&i.Invited,
		&i.InvitedTeamID,
		&i.InvitedToTeam,
		&i.Pseudonym,
		&i.InvitationSentAt,
		&i.InvitationExpiredNotifiedAt,
		&i.FieldsMissing,
	)
	return i, err
}
